'use strict';
// Content-progress view. Keep production API semantics separate from the browser file adapter.
const progressBase={modalContent,handleAction,closeModal,parseUploadRecord};
const PROGRESS_LABEL={uploading:'上传中',pending:'排队中',processing:'识别中',done:'已完成',failed:'失败',stuck:'积压'};
const PROGRESS_SIZES=[10,15,20,30,50,100];
let progressPageSizes={};try{const saved=JSON.parse(localStorage.getItem('audit-progress-page-sizes')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))progressPageSizes=saved;}catch{}
storageQuota.maxConcurrencyLocal??=4;storageQuota.maxConcurrencyOss??=32;
storageQuota.concurrencyLocal=Math.min(storageQuota.maxConcurrencyLocal,storageQuota.concurrencyLocal||1);
storageQuota.concurrencyOss=Math.min(storageQuota.maxConcurrencyOss,storageQuota.concurrencyOss||5);
function progressOwner(d){const who=state.libraryIdentity?.id||'current-user';return(d.uploader_id??d.ownerId??(!d.owner||d.owner==='当前用户'?who:d.owner))===who;}
function progressRows(space='全部空间'){
 return state.docs.filter(d=>!d.deleted&&!d.refSourceId&&auditFileAccess(d).read&&(space==='全部空间'||d.space===space)&&(d.space!=='个人空间'||progressOwner(d))&&(!(d.source==='OSS'||d.is_oss)||d.space==='公共空间')).map(doc=>{
  const record=state.uploads.find(r=>r.id===doc.id),source=doc.source==='OSS'||doc.is_oss?'OSS':'LOCAL',job=libParseQueue.find(j=>j.doc.id===doc.id);
  let status=record?.contentStatus||doc.content_status||(Object.hasOwn(PROGRESS_LABEL,record?.status)?record.status:null);
  if(!Object.hasOwn(PROGRESS_LABEL,status)){status=doc.importedOnly?'pending':doc.parseError?'failed':!doc.local?'done':record?.status==='正在上传'?'uploading':record?.status==='正在解析'?'processing':job?'pending':record?.queueCleared||record?.status==='已停止'||record?.error?.includes('未完成')?'stuck':'pending';}
  return{doc,record,source,status,id:doc.id,fileId:record?.file_id||doc.file_id||doc.id,name:doc.name,bucket:record?.bucket||doc.bucket||'—',folder:folderPath(doc.folder)||'根目录',updated:record?.updatedAt||record?.updated_at||doc.content_updated_at||doc.updated_at||doc.uploadedAt||record?.time||doc.date||'—',error:record?.error||record?.last_error||doc.parseError||doc.error_message||'',selfUpload:source==='LOCAL'&&progressOwner(doc)};
 }).sort((a,b)=>(Date.parse(b.updated)||0)-(Date.parse(a.updated)||0));
}
function progressFiltered(p=modalData){return progressRows(p.space).filter(r=>(!p.query||r.name.toLowerCase().includes(p.query.toLowerCase()))&&(!p.status||r.status===p.status)&&(!p.source||r.source===p.source));}
function progressInit(p={}){p.space||=state.space;p.query??='';p.queryDraft??=p.query;p.status??='';p.source??='';p.selected??=[];p.page??=1;p.pageSize=PROGRESS_SIZES.includes(p.pageSize)?p.pageSize:(PROGRESS_SIZES.includes(progressPageSizes[p.space])?progressPageSizes[p.space]:20);p.views??={};p.updatedAt??=new Date().toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});return p;}
function progressStopTimer(){if(recordsAutoTimer){clearInterval(recordsAutoTimer);recordsAutoTimer=null;}}
function progressStartTimer(p){progressStopTimer();if(p.auto)recordsAutoTimer=setInterval(()=>{if(modal==='upload-records'&&modalData===p)progressRefresh(p);},8000);}
function progressOpen(p={}){progressInit(p);openModal('upload-records',p);progressStartTimer(p);}
function progressRefresh(p){p.updatedAt=new Date().toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});p.refreshCount=(p.refreshCount||0)+1;const readable=new Set(progressRows(p.space).map(r=>r.id));p.selected=p.selected.filter(id=>readable.has(id));paintModal();}
function progressTime(value){const text=String(value);if(/^\d{4}-\d{2}-\d{2}$/.test(text))return text;const date=new Date(text);return Number.isNaN(date.getTime())?text:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date);}
function progressTone(status){return status==='done'?'green':['failed','stuck','missing'].includes(status)?'red':status==='processing'?'blue':'amber';}
function progressTimeline(r){const up=r.source==='OSS'?'同步接入':r.selfUpload?'上传':'资料接入',upText=r.status==='uploading'?Math.max(0,Math.min(100,r.record?.upload_percent??r.record?.progress??0))+'%':'已完成',full=r.status==='uploading'?'等待上传完成':PROGRESS_LABEL[r.status];return'<div class="progress-timeline"><span><i class="progress-stage-dot '+(r.status==='uploading'?'amber':'green')+'"></i><span>'+up+'</span><b>'+upText+'</b></span><span><i class="progress-stage-dot '+progressTone(r.status)+'"></i><span>全文识别</span><b>'+E(full)+'</b></span></div>';}
function progressSummary(rows){const count=s=>rows.filter(r=>r.status===s).length;return[['uploading','上传中',count('uploading')],['pending','排队中',count('pending')],['processing','识别中',count('processing')],['done','已完成',count('done')],['problem','失败 / 积压',count('failed')+count('stuck')]];}
function progressCanRetry(r){return!!r&&auditFileAccess(r.doc).parse&&!['uploading','processing','done'].includes(r.status)&&!libParsePromises.has(r.id);}
function progressSub(type,data={}){openModal(type,{back:modalData,...data});}
function progressDialog(){
 const p=progressInit(modalData),all=progressRows(p.space),rows=progressFiltered(p),pages=Math.max(1,Math.ceil(rows.length/p.pageSize));p.page=Math.max(1,Math.min(p.page,pages));const shown=pageItems(rows,p.page,p.pageSize),allChecked=shown.length&&shown.every(r=>p.selected.includes(r.id));
 const tabs=['全部空间',...SPACE_ORDER].map(s=>B(s,'lib-record-space',p.space===s?'soft sm':'ghost sm','data-space="'+s+'" aria-pressed="'+(p.space===s)+'"')).join('');
 const stats=progressSummary(all).map(([code,name,count])=>'<button class="progress-stat" data-action="progress-stat" data-status="'+code+'" title="筛选'+name+'"><span>'+name+'</span><strong class="'+(code==='done'?'green':code==='problem'?'red':'')+'">'+count+'</strong></button>').join('');
 const publicRows=progressRows('公共空间'),ossRemaining=publicRows.filter(r=>r.source==='OSS'&&r.status!=='done').length,queue=libParseQueue.length;
 const oss=p.space==='公共空间'?'<div class="progress-oss-line"><span>OSS 尚缺全文 <b>'+ossRemaining+'</b></span><span title="全部空间的待识别队列，不含正在识别的任务">待识别队列 <b>'+queue+'</b></span>'+(state.libraryAdmin?B('OSS 补全文','lib-record-fill','sm soft'):'')+'</div>':'';
 const table='<div class="progress-table-scroll"><table class="table progress-table"><thead><tr><th class="progress-check"><input type="checkbox" aria-label="选择本页上传记录" data-progress-change="page-check" '+(allChecked?'checked':'')+' '+(!shown.length?'disabled':'')+'></th><th class="progress-name">文件名称 / 位置</th><th class="progress-source">来源</th><th class="progress-stage">处理进度</th><th class="progress-status">状态</th><th class="progress-time">更新时间</th><th class="progress-action">操作</th></tr></thead><tbody>'+shown.map(r=>'<tr data-progress-id="'+E(r.id)+'"><td><input type="checkbox" aria-label="选择上传记录 '+E(r.name)+'" data-progress-change="check" data-id="'+E(r.id)+'" '+(p.selected.includes(r.id)?'checked':'')+'></td><td><b class="progress-filename" title="'+E(r.name)+'">'+E(r.name)+'</b><div class="progress-filepath" title="'+E(r.doc.space+' / '+r.folder)+'">'+E(r.doc.space+' / '+r.folder)+'</div>'+(r.error?'<div class="progress-row-error" title="'+E(r.error)+'">'+E(r.error)+'</div>':'')+'</td><td>'+tag(r.source==='OSS'?'OSS 同步':'本地上传',r.source==='OSS'?'':'blue')+'</td><td>'+progressTimeline(r)+'</td><td>'+tag(PROGRESS_LABEL[r.status],progressTone(r.status))+'</td><td class="progress-updated" title="'+E(r.updated)+'">'+E(progressTime(r.updated))+'</td><td>'+A('详情','progress-detail','data-id="'+E(r.id)+'"')+(r.status==='done'?'<button class="link" data-action="progress-open" data-id="'+E(r.id)+'" '+(auditFileAccess(r.doc).preview?'':'disabled')+'>查看全文</button>':'')+'</td></tr>').join('')+(!shown.length?'<tr><td colspan="7"><div class="progress-empty">没有符合条件的上传记录</div></td></tr>':'')+'</tbody></table></div>';
 const scope=p.space==='个人空间'?'仅显示本人可见的上传记录':p.space==='公共空间'?'公共资料与 OSS 同步记录':p.space==='项目空间'?'当前有权查看的项目资料':'仅显示有权查看的资料';
 const query='<div class="progress-filterbar"><input id="lib-record-query" aria-label="搜索上传记录" placeholder="搜索文件名" data-progress-input="query" value="'+E(p.queryDraft)+'"><select aria-label="上传记录状态" data-progress-change="status"><option value="">全部状态</option>'+Object.entries(PROGRESS_LABEL).map(([v,n])=>'<option value="'+v+'" '+(p.status===v?'selected':'')+'>'+n+'</option>').join('')+'<option value="problem" '+(p.status==='problem'?'selected':'')+'>失败 / 积压</option></select>'+(['全部空间','公共空间'].includes(p.space)?'<select aria-label="上传记录来源" data-progress-change="source"><option value="">全部来源</option><option value="LOCAL" '+(p.source==='LOCAL'?'selected':'')+'>本地上传</option><option value="OSS" '+(p.source==='OSS'?'selected':'')+'>OSS 同步</option></select>':'')+B('查询','progress-search','sm')+B('重新开始识别'+(p.selected.length?'（'+p.selected.length+'）':''),'lib-record-retry','soft sm',p.selected.length?'':'disabled')+'</div>';
 const body='<div class="progress-viewbar"><div class="lib-record-tabs">'+tabs+'</div><span class="progress-scope">'+scope+'</span></div><div class="progress-stats">'+stats+'</div>'+oss+query+(p.notice?'<div class="progress-notice" role="status">'+E(p.notice)+'</div>':'')+table+'<div class="progress-pagination"><span>共 '+rows.length+' 条'+(p.selected.length?' · 已选 '+p.selected.length+' 条':'')+'</span><div class="row"><select aria-label="上传记录每页数量" data-progress-change="page-size">'+PROGRESS_SIZES.map(n=>'<option value="'+n+'" '+(p.pageSize===n?'selected':'')+'>'+n+' 条/页</option>').join('')+'</select>'+B('上页','lib-record-prev','sm',p.page<=1?'disabled':'')+'<span>'+p.page+' / '+pages+'</span>'+B('下页','lib-record-next','sm',p.page>=pages?'disabled':'')+'<label class="progress-jump">跳至<input type="number" min="1" max="'+pages+'" aria-label="上传记录跳转页码" id="progress-page-jump" value="'+p.page+'"></label>'+B('确定','progress-jump','sm')+'</div></div>';
 const node=document.createElement('div');node.innerHTML=modalFrame('上传记录','',body,'','progress-dialog');const actions=document.createElement('div');actions.className='progress-head-actions';actions.innerHTML='<span class="progress-refreshed" title="最近刷新时间">'+p.updatedAt+'</span>'+B(I('refresh','icon-sm')+'刷新','lib-record-refresh','sm')+B(p.auto?'停止自动刷新':'自动刷新','lib-record-auto','sm')+((state.libraryAdmin||['公共空间','个人空间'].includes(p.space))?'<details class="lib-dropdown progress-head-more"><summary class="btn sm" aria-label="更多上传记录操作">更多'+I('down','icon-sm')+'</summary><div class="lib-menu">'+(['公共空间','个人空间'].includes(p.space)?B('补全本地缺失全文','progress-local-fill','ghost sm'):'')+(state.libraryAdmin?B('识别服务管理','progress-admin','ghost sm')+B('清空 OCR 队列','lib-record-clear','ghost danger sm'):'')+'</div></details>':'');node.querySelector('.modalhead>button').before(actions);return node.innerHTML;
}
function progressRetryConfirm(ids,kind='selected'){
 const p=modalData,readable=progressRows(p.space),requested=kind==='oss'?progressRows('公共空间').filter(r=>r.source==='OSS'&&r.status!=='done'):kind==='local'?progressRows(p.space).filter(r=>r.source==='LOCAL'&&!r.doc.text?.trim()):ids.map(id=>readable.find(r=>r.id===id)).filter(Boolean),accepted=requested.filter(progressCanRetry),skipped=requested.length-accepted.length;
 progressSub('progress-retry',{ids:accepted.map(r=>r.id),kind,requested:requested.length,skipped});
}
async function progressEnqueue(ids,p){
 const report={enqueued:0,missing:0,skipped:0},allowed=new Set(progressRows('全部空间').map(r=>r.id));
 for(const id of ids){const r=progressRows('全部空间').find(r=>r.id===id);if(!allowed.has(id)||!progressCanRetry(r)){report.skipped++;continue;}const source=uploadSources.get(id)||await libGetFile(id);if(!source){report.missing++;continue;}if(!auditFileAccess(r.doc).parse||!progressCanRetry(progressRows('全部空间').find(x=>x.id===id))){report.skipped++;continue;}
  const doc=r.doc,record=r.record||{id,name:doc.name,target:doc.space+' / '+doc.folder,time:new Date().toLocaleString('zh-CN')};if(!r.record)state.uploads.unshift(record);doc.local=true;doc.importedOnly=false;doc.parseError=null;record.error=null;record.contentStatus=null;doc.content_status=null;record.cancelPending=false;record.queueCleared=false;record.failedQueueCleared=false;record.updatedAt=new Date().toISOString();uploadSources.set(id,source);parseUploadRecord(record,doc,source);report.enqueued++;
 }
 p.selected=p.selected.filter(id=>!ids.includes(id));p.notice='已入队 '+report.enqueued+' 条'+(report.missing?'；'+report.missing+' 条需在详情中补充原文件':'')+(report.skipped?'；跳过 '+report.skipped+' 条（处理中或权限变化）':'');persist();if(modal==='upload-records'&&modalData===p)paintModal();return report;
}
function progressClearQueue(options){
 const result={LOCAL:0,OSS:0,processing:0,failed:0};
 for(const row of progressRows('全部空间')){const pool=row.source,record=row.record;if(!record)continue;
  if(options[pool]&&row.status==='pending'&&!['正在解析'].includes(record.status)){record.cancelPending=true;record.queueCleared=true;record.status='已停止';record.contentStatus='stuck';record.error='已移出识别队列，可重新开始识别。';record.updatedAt=new Date().toISOString();result[pool]++;}
  if(options.processing&&row.status==='processing'){record.processingMarkerCleared=true;result.processing++;}
  if(options.failed&&row.status==='failed'&&!record.failedQueueCleared){record.failedQueueCleared=true;result.failed++;}
 }
 libDrainParseQueue();persist();return result;
}
modalContent=function(){const p=modalData;
 if(modal==='upload-records')return progressDialog();
 if(modal==='progress-detail'){const r=progressRows('全部空间').find(r=>r.id===p.id);if(!r)return modalFrame('记录详情','','<p>资料已不可见，请返回刷新列表。</p>',B('返回记录','close-modal'),'medium');return modalFrame('记录详情',E(r.name),'<div class="progress-detail-state">'+tag(PROGRESS_LABEL[r.status],progressTone(r.status))+progressTimeline(r)+'</div>'+simpleTable(['项目','内容'],[['文件 ID',E(r.fileId)],['存储桶',E(r.bucket)],['来源',r.source==='OSS'?'OSS 同步':'本地上传'],['位置',E(r.doc.space+' / '+r.folder)],['更新时间',E(progressTime(r.updated))]],true)+(r.error?'<div class="progress-detail-error">'+E(r.error)+'</div>':'')+libErrorHtml,B('返回记录','close-modal')+(r.status==='done'?B('查看全文','progress-open','primary','data-id="'+E(r.id)+'"'):'')+(progressCanRetry(r)?B('重新开始识别','progress-retry-one','soft','data-id="'+E(r.id)+'"')+B('补充原文件','progress-reselect','sm','data-id="'+E(r.id)+'"'):''),'medium');}
 if(modal==='progress-admin'){if(!state.libraryAdmin)return modalFrame('服务管理','','<p>没有管理权限。</p>',B('返回','close-modal'),'small');return modalFrame('识别服务管理','设置对所有空间生效，当前运行任务继续完成。','<div class="form-grid">'+libForm('本地上传识别并发','lib-concurrency-local',String(storageQuota.concurrencyLocal),'type="number" min="1" max="'+storageQuota.maxConcurrencyLocal+'"')+libForm('OSS 同步识别并发','lib-concurrency-oss',String(storageQuota.concurrencyOss),'type="number" min="1" max="'+storageQuota.maxConcurrencyOss+'"')+'</div><p class="hint mt">当前服务上限：本地 '+storageQuota.maxConcurrencyLocal+'，OSS '+storageQuota.maxConcurrencyOss+'。</p><div class="progress-admin-tools">'+B('OSS 补全文','progress-admin-fill','sm')+B('清空 OCR 队列','lib-record-clear','danger sm')+'</div>'+libErrorHtml,B('取消','close-modal')+B('保存并发设置','lib-record-save-concurrency','primary'),'medium');}
 if(modal==='progress-retry')return modalFrame(p.kind==='oss'?'OSS 补全文':p.kind==='local'?'补全本地缺失全文':'重新开始识别',p.kind==='oss'?'范围：公共空间尚缺全文的 OSS 资料，不受当前筛选影响。':p.kind==='local'?'范围：当前空间有权限且全文为空的本地资料；不含 OSS，不受当前筛选影响。':'只处理所选资料；已完成、正在处理或无重新识别权限的记录将跳过。','<p>本次检查 '+p.requested+' 条，可重新入队 '+p.ids.length+' 条'+(p.skipped?'，跳过 '+p.skipped+' 条。':'。')+'</p><p class="hint mt">入队后仍需等待识别完成。缺少原文件的资料会单独提示，不会标记为成功。</p>'+libErrorHtml,B('取消','close-modal')+B('确认入队','progress-confirm-retry','primary',p.ids.length?'':'disabled'),'medium');
 if(modal==='progress-clear')return modalFrame('清空 OCR 队列','作用范围：所有空间的识别服务队列。','<p>尚未开始的任务将被移出队列；正在识别的任务仍可能完成。原文件和已有全文保留。</p><div class="progress-clear-options">'+[['LOCAL','清空本地上传待识别队列'],['OSS','清空 OSS 待识别队列'],['processing','清除“识别中”标记（慎用）'],['failed','清空失败队列']].map(([v,n])=>'<label class="row-radio"><input type="checkbox" data-progress-change="clear" value="'+v+'" '+(p.options[v]?'checked':'')+'>'+n+'</label>').join('')+'</div>'+libErrorHtml,B('取消','close-modal')+B('确认清空','lib-record-confirm-clear','danger'),'medium');
 if(modal==='progress-reselect')return modalFrame('补充原文件','核对文件名称和大小后重新识别。','<p>'+E(file(p.id)?.name||'资料已不可见')+'</p><input type="file" id="progress-source-file" aria-label="选择原文件" class="mt">'+libErrorHtml,B('取消','close-modal'),'medium');
 return progressBase.modalContent();
};
handleAction=function(action,el){
 if(action==='upload-records'){progressOpen({space:state.space});return;}
 if(action==='progress-open'){const r=progressRows('全部空间').find(r=>r.id===el.dataset.id);if(!r||r.status!=='done'||!auditFileAccess(r.doc).preview)return libError('当前资料尚无可查看的全文，或没有查看权限。');return progressBase.handleAction('source',el);}
 if(action==='progress-detail'){progressSub('progress-detail',{id:el.dataset.id});return;}
 if(action==='progress-reselect'){const r=progressRows('全部空间').find(r=>r.id===el.dataset.id);if(!progressCanRetry(r))return libError('没有重新识别权限，或任务正在处理中。');openModal('progress-reselect',{id:r.id,back:modalData.back||modalData});return;}
 if(action==='progress-retry-one'){const back=modalData.back;progressOpen(back);progressRetryConfirm([el.dataset.id]);return;}
 if(action==='progress-confirm-retry'){if(modalData.kind==='oss'&&!state.libraryAdmin)return libError('没有服务管理权限。');const ids=modalData.ids,back=modalData.back;progressOpen(back);progressEnqueue(ids,back);return;}
 if(action==='progress-admin'){if(state.libraryAdmin)progressSub('progress-admin');return;}
 if(action==='progress-admin-fill'){if(!state.libraryAdmin)return;const back=modalData.back;progressOpen(back);progressRetryConfirm([],'oss');return;}
 if(action==='progress-local-fill'){if(['公共空间','个人空间'].includes(modalData.space))progressRetryConfirm([],'local');return;}
 if(action==='progress-search'){modalData.query=modalData.queryDraft.trim();modalData.page=1;paintModal();return;}
 if(action==='progress-stat'){modalData.status=el.dataset.status;modalData.page=1;paintModal();return;}
 if(action==='progress-jump'){const page=Number($('#progress-page-jump').value),max=Math.max(1,Math.ceil(progressFiltered().length/modalData.pageSize));if(!Number.isInteger(page)||page<1||page>max)return toast('请输入1至'+max+'之间的页码。');modalData.page=page;paintModal();return;}
 if(!action.startsWith('lib-record-'))return progressBase.handleAction(action,el);
 const p=modalData;
 switch(action){
  case 'lib-record-space':{const old=p.space;p.views[old]={query:p.query,queryDraft:p.queryDraft,status:p.status,source:p.source,page:p.page,pageSize:p.pageSize,selected:[...p.selected]};const next=el.dataset.space;Object.assign(p,{query:'',queryDraft:'',status:'',source:'',page:1,pageSize:progressPageSizes[next]||20,selected:[]},p.views[next]||{},{space:next});paintModal();break;}
  case 'lib-record-refresh':progressRefresh(p);break;
  case 'lib-record-auto':p.auto=!p.auto;progressStartTimer(p);paintModal();break;
  case 'lib-record-prev':p.page--;paintModal();break;
  case 'lib-record-next':p.page++;paintModal();break;
  case 'lib-record-retry':progressRetryConfirm(p.selected);break;
  case 'lib-record-retry-one':progressRetryConfirm([el.dataset.id]);break;
  case 'lib-record-fill':if(state.libraryAdmin)progressRetryConfirm([],'oss');break;
  case 'lib-record-save-concurrency':{if(!state.libraryAdmin)return libError('没有服务管理权限。');const a=Number($('#lib-concurrency-local').value),b=Number($('#lib-concurrency-oss').value);if(!Number.isInteger(a)||a<1||a>storageQuota.maxConcurrencyLocal||!Number.isInteger(b)||b<1||b>storageQuota.maxConcurrencyOss)return libError('请输入服务上限内的整数：本地1–'+storageQuota.maxConcurrencyLocal+'，OSS 1–'+storageQuota.maxConcurrencyOss+'。');storageQuota.concurrencyLocal=a;storageQuota.concurrencyOss=b;persist();libDrainParseQueue();const back=p.back;progressOpen(back);back.notice='并发设置已保存：本地 '+a+'，OSS '+b+'。';paintModal();break;}
  case 'lib-record-clear':if(state.libraryAdmin)openModal('progress-clear',{back:p.back||p,options:{LOCAL:true,OSS:true,processing:false,failed:false}});break;
  case 'lib-record-confirm-clear':{if(!state.libraryAdmin)return libError('没有服务管理权限。');if(!Object.values(p.options).some(Boolean))return libError('请至少选择一项。');const result=progressClearQueue(p.options),back=p.back;back.notice='已移出队列：本地 '+result.LOCAL+' 条、OSS '+result.OSS+' 条；清除识别中标记 '+result.processing+' 条、失败队列 '+result.failed+' 条。运行中的识别继续完成。';progressOpen(back);break;}
 }
};
closeModal=function(){if(modal?.startsWith('progress-')&&modalData.back){progressOpen(modalData.back);return;}if(modal==='upload-records')progressStopTimer();return progressBase.closeModal();};
window.addEventListener('input',event=>{if(event.target.dataset.progressInput==='query'){event.stopImmediatePropagation();modalData.queryDraft=event.target.value;}},true);
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal==='upload-records'){const menu=document.querySelector('.progress-head-more[open]');if(menu){event.preventDefault();event.stopImmediatePropagation();menu.open=false;menu.querySelector('summary').focus();return;}}if(event.target.id==='lib-record-query'&&event.key==='Enter'){event.preventDefault();event.stopImmediatePropagation();handleAction('progress-search',event.target);}},true);
window.addEventListener('change',async event=>{const el=event.target,k=el.dataset.progressChange;
 if(k){event.stopImmediatePropagation();const p=modalData;if(k==='clear'){p.options[el.value]=el.checked;return;}if(k==='check')p.selected=el.checked?[...new Set([...p.selected,el.dataset.id])]:p.selected.filter(id=>id!==el.dataset.id);if(k==='page-check'){const ids=pageItems(progressFiltered(),p.page,p.pageSize).map(r=>r.id);p.selected=el.checked?[...new Set([...p.selected,...ids])]:p.selected.filter(id=>!ids.includes(id));}if(k==='status'){p.status=el.value;p.page=1;}if(k==='source'){p.source=el.value;p.page=1;}if(k==='page-size'){p.pageSize=Number(el.value);p.page=1;progressPageSizes[p.space]=p.pageSize;localStorage.setItem('audit-progress-page-sizes',JSON.stringify(progressPageSizes));}paintModal();return;}
 if(el.id==='progress-source-file'){event.stopImmediatePropagation();const p=modalData,f=el.files[0],d=file(p.id);if(!f||!d)return;if(f.name!==d.name||d.byteSize!=null&&f.size!==d.byteSize)return libError('所选文件与原资料名称或大小不一致，请选择原文件。');if(f.size>100*1024*1024)return libError('单文件不能超过100MB。');if(!auditFileAccess(d).parse)return libError('权限已变化，无法补充原文件。');await libStoreFile(d.id,f);uploadSources.set(d.id,f);if(modal!=='progress-reselect'||modalData!==p)return;progressOpen(p.back);progressEnqueue([d.id],p.back);}
},true);
const progressActualParse=recordsBase.parseUploadRecord;
recordsBase.parseUploadRecord=function(record,doc,source){record.updatedAt=new Date().toISOString();record.contentStatus=null;doc.content_status=null;return progressActualParse(record,doc,source).finally(()=>{record.updatedAt=new Date().toISOString();persist();if(modal==='upload-records')paintModal();});};
parseUploadRecord=function(record,doc,source){if(record.queueCleared){record.status='已停止';record.contentStatus='stuck';return Promise.resolve();}record.updatedAt=new Date().toISOString();return progressBase.parseUploadRecord(record,doc,source);};
// Combined problem filter is a view convenience, not a new backend status.
const progressFilterBase=progressFiltered;
progressFiltered=function(p=modalData){if(p.status==='problem')return progressFilterBase({...p,status:''}).filter(r=>['failed','stuck'].includes(r.status));return progressFilterBase(p);};
document.addEventListener('click',event=>{const button=event.target.closest?.('.progress-head-more .lib-menu button');if(button)button.closest('details').open=false;},true);
document.addEventListener('click',event=>{document.querySelectorAll('.progress-head-more[open]').forEach(menu=>{if(!menu.contains(event.target))menu.open=false;});});
render();
